#include<iostream>
#include<ros/ros.h>
#include <tf/transform_broadcaster.h>
#include<nav_msgs/Odometry.h>
#include<std_msgs/Float32MultiArray.h>
#include<vector>
#include <check_license/libLicense.h>
using namespace std;

//subscribe and publish
ros::Subscriber encoder_sub;
ros::Publisher  odom_pub; 

nav_msgs::Odometry odom_msg;
float    last_time=-1;    //last time get the data;
float    last_th=0;

// launch  param
string  odom_frame;  
string  base_frame;
bool    is_publish_tf;

void encoderHandler(const std_msgs::Float32MultiArray::ConstPtr & encoder_msg)
{
    vector<float> data=encoder_msg->data;
    if(data.size()<5)
        return;
    if(last_time<0)
    {
        last_time=data[2];
        float now_th;
        last_th=now_th=0;
        odom_msg.header.stamp=ros::Time::now();

        odom_msg.pose.pose.orientation.w=1;
        odom_pub.publish(odom_msg);
        if(is_publish_tf)
        {
            tf::TransformBroadcaster odom_tf;
            tf::Transform transform;
            transform.setOrigin( tf::Vector3(odom_msg.pose.pose.position.x,odom_msg.pose.pose.position.y, 0.0) );
            tf::Quaternion q;
            q.setRPY(0, 0, now_th);
            transform.setRotation(q);
            odom_tf.sendTransform(tf::StampedTransform(transform, ros::Time::now(),odom_frame, base_frame));
        }
        return;
    }
    else 
    {
        float v_left=data[0]*data[3];
        float v_right=data[1]*data[3];
        float v_x=(v_left+v_right)/2;
        float v_th=(v_right-v_left)/data[4];
        float deltaTime=(data[2]-last_time)/1000.0;
        float now_th=last_th+v_th*deltaTime;
        float deltaX=v_x*deltaTime*cos(last_th);
        float deltaY=v_x*deltaTime*sin(last_th);
        odom_msg.pose.pose.position.x+=deltaX;
        odom_msg.pose.pose.position.y+=deltaY;
        odom_msg.pose.pose.orientation.z=sin(now_th/2);
        odom_msg.pose.pose.orientation.w=cos(now_th/2);
        odom_msg.twist.twist.linear.x=v_x;
        odom_msg.twist.twist.angular.z=v_th;
        odom_msg.header.stamp=ros::Time::now();
        odom_pub.publish(odom_msg);
        last_th=now_th;
        last_time=data[2];

        if(is_publish_tf)
        {
            tf::TransformBroadcaster odom_tf;
            tf::Transform transform;
            transform.setOrigin( tf::Vector3(odom_msg.pose.pose.position.x,odom_msg.pose.pose.position.y, 0.0) );
            tf::Quaternion q;
            q.setRPY(0, 0, now_th);
            transform.setRotation(q);
            odom_tf.sendTransform(tf::StampedTransform(transform, ros::Time::now(),odom_frame, base_frame));
        }
    }




}
int main(int argc, char ** argv)
{
    if (chexeeckLicense() != "tkjraarjkt")
    {
        ROS_ERROR("License wrong!");
        return 0;
    }    
    ros::init(argc,argv,"chassis_odom_node");
    ros::NodeHandle nh("~");
    encoder_sub=nh.subscribe<std_msgs::Float32MultiArray>("/encoder",5,encoderHandler);
    odom_pub=nh.advertise<nav_msgs::Odometry>("/odom",5);

    nh.param("odom_frame",odom_frame,std::string("odom"));
    nh.param("base_frame",base_frame,string("base_link"));
    nh.param("is_publish_tf",is_publish_tf,false);
    odom_msg.header.frame_id=odom_frame;
    odom_msg.child_frame_id=base_frame;
    ros::spin();
    return 0;
}

